const META = JSON.parse(fs.readFileSync(path.join(__dirname, 'module.json'), 'utf8'));
const DEFAULTS = Object.fromEntries(Object.entries(META.options).map(([k, v]) => [k, v.default]));
/* every option written out, so a course's own options for the module never mix in */
const opts = over => Object.assign({}, DEFAULTS, over || {});
const BDK_OPT = opts({groups: FIX.groups, defaultGroup: 'Week 14', headTag: 'p{id}',
  intro: FIX.edition + ', page by page. Pick a quiz to see only its pages.'});
const FILE = 'dlt_tables_test.js';
const KIND = ['kse', 'bw', 'notes'];
const RECALL_FIELDS = [...new Set(BDK_OPT.recallShow.concat([BDK_OPT.recallClassField]))];

/* The detail's sections, worked out here apart from the module, from the list's text: the
   labels (module.json detailSections), the rule for a qualifier naming a drug of the same
   page (detailOwnField), and BDK's resolveSeeAbove (assets/app.js lines 331-347) as BDK
   writes it: a Set per qualifier, filled in the data's order from every row's boxed
   warnings that are not "See above", then each "See above" replaced by the Set's items. */
function expectedSections(tables){
  const H = /(Key Side Effects?|US Boxed Warnings?|Other Notes?)\s*(\([^)]*\))?\s*:/gi;
  const words = s => String(s || '').toLowerCase().replace(/^only for\s+/, '').split(/[^a-z0-9]+/).filter(Boolean);
  const kindOf = l => /^key/i.test(l) ? 'kse' : /^us/i.test(l) ? 'bw' : 'notes';
  const own = {};
  for(const t of tables){
    const firsts = new Set(t.rows.map(r => words(r.generic)[0]));
    t.rows.forEach((r, i) => {
      const e = r.essential || '', ms = [...e.matchAll(H)], mine = words(r.generic);
      own[t.id + ':' + i] = ms.map((m, k) => ({kind: kindOf(m[1]), qual: m[2] ? m[2].slice(1, -1) : '', text: e.slice(m.index + m[0].length, k + 1 < ms.length ? ms[k + 1].index : e.length).trim()}))
        .filter(p => { const w = words(p.qual); return !w.length || !firsts.has(w[0]) || w.every(x => mine.includes(x)); });
    });
  }
  const shared = {};
  for(const k of Object.keys(own)) for(const p of own[k]) if(p.kind === 'bw' && p.qual && !/^See above/i.test(p.text)) (shared[p.qual] = shared[p.qual] || new Set()).add(p.text);
  const out = {};
  for(const k of Object.keys(own)) out[k] = own[k].flatMap(p => p.kind === 'bw' && p.qual && /^See above/i.test(p.text) && shared[p.qual] ? [...shared[p.qual]].map(text => ({kind: 'bw', qual: p.qual, text})) : [p]);
  return out;
}
const splitItems = s => { const out = []; let d = 0, cur = ''; for(let i = 0; i < s.length; i++){ const c = s[i]; if(c === '(') d++; if(c === ')') d = Math.max(0, d - 1);
  if(d === 0 && s.startsWith('; ', i)){ out.push(cur.trim()); cur = ''; i++; continue; } cur += c; } out.push(cur.trim()); return out.filter(Boolean); };

let hasOwn = false;
const dataFile = tables => `/* BDK's drug list (data/decks.json, 05c36c3), added by the drug-list-tab test */\n` +
  (hasOwn ? `DRUG_TABLES.splice(0, DRUG_TABLES.length, ...${JSON.stringify(tables)});` : `const DRUG_TABLES = ${JSON.stringify(tables)};`) + '\n';
const build = (label, tables, o) => L.scratchBuild(label, {files: {[FILE]: dataFile(tables)},
  courseLine: `COURSE.files = (COURSE.files || ['atlas.js', 'diagrams.js', 'q1_topics.js']).concat([${JSON.stringify(FILE)}]);` + L.featureOn(__dirname, o)});
const clone = x => JSON.parse(JSON.stringify(x));
const lc = v => String(v == null ? '' : v).toLowerCase();
const expectRows = (tables, fields, term) => tables.flatMap(t => t.rows.map((r, i) => [t.id, i, r]))
  .filter(([, , r]) => fields.some(f => lc(r[f]).includes(term.toLowerCase()))).map(([id, i]) => `${id}:${i}`);
const groupIds = g => g.tables === 'all' ? FIX.tables.map(t => String(t.id)) : FIX.tables.filter(t => g.tables.includes(t.id)).map(t => String(t.id));

/* the state no part of the tab may write */
const snapshot = page => page.evaluate(async () => {
  const dump = s => { const o = {}; for(let i = 0; i < s.length; i++){ const k = s.key(i); o[k] = s.getItem(k); } return o; };
  let idb = null;
  try { idb = indexedDB.databases ? (await indexedDB.databases()).map(d => d.name).sort() : 'no list'; } catch(e){ idb = 'error ' + e.message; }
  return JSON.stringify({ls: dump(localStorage), ss: dump(sessionStorage), db: JSON.stringify(DB), idb});
});
