const consoleTrap = () => { window.__writes = [];
  const S = Storage.prototype;
  for(const f of ['setItem', 'removeItem', 'clear']){ const o = S[f]; S[f] = function(k){ try { window.__writes.push([f, this === sessionStorage ? 'ss' : 'ls', String(k)]); } catch(e){} return o.apply(this, arguments); }; }
  try { const io = indexedDB.open.bind(indexedDB); indexedDB.open = function(n){ window.__writes.push(['open', 'idb', String(n)]); return io.apply(null, arguments); }; } catch(e){}
  window.__cerr = []; const o = console.error;
  console.error = function(){ try { window.__cerr.push([...arguments].map(String).join(' ')); } catch(e){} return o.apply(this, arguments); }; };
const shownIds = page => page.$$eval('#v-' + BDK_OPT.tab + ' [data-body] section[data-table]', s => s.map(e => e.dataset.table));
const sideways = page => page.evaluate(() => document.documentElement.scrollWidth > window.innerWidth);
const pane = '#v-' + BDK_OPT.tab;

async function bdkView(browser, file, width){
  const tag = ` (${width} px)`;
  const {ctx, page, errors} = await L.openPage(browser, file, {viewport: {width, height: 900}}, consoleTrap);
  const cerr = []; page.on('console', m => { if(m.type() === 'error') cerr.push(m.text()); });
  const before = await snapshot(page);
  await page.evaluate(() => { window.__writes = []; });
  const nav = await page.$(`#nav button[data-v="${BDK_OPT.tab}"]`);
  check(!!nav && (await nav.textContent()) === BDK_OPT.label, `the nav has the ${BDK_OPT.label} tab` + tag);
  await nav.click();
  check(await page.evaluate(p => !document.querySelector(p).classList.contains('hide'), pane), 'the tab opens its pane' + tag);
  const wk14 = FIX.groups.find(g => g.label === BDK_OPT.defaultGroup);
  check(JSON.stringify(await shownIds(page)) === JSON.stringify(groupIds(wk14)), `opens on the default group's pages (${BDK_OPT.defaultGroup}: ${groupIds(wk14).join(', ')})` + tag, await shownIds(page));
  check(await page.$eval(`${pane} [data-listgroup][aria-pressed="true"]`, b => b.textContent.trim().startsWith('Week 14')), 'and its chip is pressed' + tag);
  check((await page.$eval(`${pane} .sub`, e => e.textContent)) === BDK_OPT.intro, 'the intro line is BDK\'s' + tag);

  // each group chip shows exactly its tables, in order, with the jump strip to them
  const chips = await page.$$eval(`${pane} [data-listgroup]`, b => b.map(x => [x.dataset.listgroup, x.textContent.replace(/\s+/g, ' ').trim()]));
  check(chips.length === FIX.groups.length + 1 && chips[0][1] === 'All pages', `${chips.length} chips: All pages and the ${FIX.groups.length} groups`, chips.map(c => c[1]));
  const badGroups = [], badJump = [], badCount = [];
  for(const [i, text] of chips){
    await page.click(`${pane} [data-listgroup="${i}"]`);
    const want = +i < 0 ? FIX.tables.map(t => String(t.id)) : groupIds(FIX.groups[+i]);
    const got = await shownIds(page);
    if(JSON.stringify(got) !== JSON.stringify(want)) badGroups.push(`${text}: ${got.join(',')}`);
    const jump = await page.$$eval(`${pane} .jump a.pchip`, a => a.map(x => [x.textContent, x.getAttribute('href'), !!document.getElementById(x.getAttribute('href').slice(1))]));
    if(JSON.stringify(jump.map(j => j[0])) !== JSON.stringify(want) || !jump.every(j => j[2])) badJump.push(text);
    if(+i >= 0){
      const g = FIX.groups[+i], ids = groupIds(g), cnt = ids.length > 6 ? '' : ' p' + ids.slice().sort((a, b) => a - b).join(', ');
      if(text !== g.label + cnt) badCount.push(`${text} (want ${g.label + cnt})`);
    }
  }
  check(!badGroups.length, 'each group chip shows exactly its tables, in the data\'s order' + tag, badGroups);
  check(!badJump.length, 'the jump strip names each table shown and each link reaches its table' + tag, badJump);
  check(!badCount.length, 'a chip of six tables or fewer lists them, as BDK\'s does' + tag, badCount);

  // All pages: every table, its title, tag, headings, legend and every row
  await page.click(`${pane} [data-listgroup="-1"]`);
  const tables = await page.$$eval(`${pane} [data-body] section[data-table]`, s => s.map(e => ({id: e.dataset.table,
    title: e.querySelector('h3').firstChild.textContent.trim(), ed: e.querySelector('h3 .ed').textContent,
    th: [...e.querySelectorAll('th')].map(x => x.textContent), thf: [...e.querySelectorAll('th')].map(x => x.dataset.field), rows: e.querySelectorAll('tbody tr[data-ref]').length,
    legend: (e.querySelector('.legend') || {}).textContent || ''})));
  const heads = BDK_OPT.columns.map(c => c[1]);
  const badT = FIX.tables.filter((t, k) => { const g = tables[k]; return !g || g.id !== String(t.id) || g.title !== t.title || g.ed !== 'p' + t.id ||
    JSON.stringify(g.th) !== JSON.stringify(heads) || g.rows !== t.rows.length || g.legend !== (t.legend || ''); }).map(t => t.id);
  check(tables.length === FIX.tables.length && !badT.length, `All pages: ${tables.length} tables, each with its title, p<page>, BDK's five headings, its legend and every row (${FIX.tables.reduce((n, t) => n + t.rows.length, 0)} rows)` + tag, badT);
  const badF = tables.filter(g => JSON.stringify(g.thf) !== JSON.stringify(BDK_OPT.columns.map(c => c[0]))).map(g => g.id);
  check(tables.length && !badF.length, 'every column heading carries its column\'s field (data-field), the hook field-colours colours' + tag, badF);
  const cell = await page.$eval(`${pane} tr[data-ref="${FIX.tables.findIndex(t => t.id === 10)}:0"]`, tr => [...tr.children].map(td => td.textContent.trim()));
  const r10 = FIX.tables.find(t => t.id === 10).rows[0];
  check(cell.length === 5 && cell[1] === r10.generic && cell[4] === r10.indication + 'Activity against: ' + r10.activity, 'a row\'s cells hold its fields, with "Activity against:" under the indications', cell);
  check(!(await sideways(page)), 'no sideways scroll with every table shown' + tag);
  check(!(await page.$(`${pane} [data-listview]`)), 'no image view: BDK\'s data gives no image per table' + tag);

  // search: every page, and a drug outside the chosen group
  await page.click(`${pane} [data-listgroup="${FIX.groups.indexOf(wk14)}"]`);
  await page.fill(`${pane} [data-q]`, 'methadone');
  const m = {rows: await page.$$eval(`${pane} tr[data-ref]`, t => t.map(x => x.dataset.ref)), ids: await shownIds(page),
    note: await page.$eval(`${pane} [data-body]`, b => (b.querySelector('[data-allnote]') || {}).textContent || '')};
  const wantM = expectRows(FIX.tables, BDK_OPT.searchFields, 'methadone').map(r => { const [id, i] = r.split(':'); return FIX.tables.findIndex(t => String(t.id) === id) + ':' + i; });
  check(m.rows.length > 0 && JSON.stringify(m.rows) === JSON.stringify(wantM), `search covers every page: "methadone" with Week 14 chosen finds its ${wantM.length} rows, on page(s) ${m.ids.join(', ')}` + tag, m);
  check(!groupIds(wk14).some(id => m.ids.includes(id)) && m.ids.includes('25'), 'those rows are on pages outside the chosen group' + tag, m.ids);
  check(m.note === 'Showing matches from all pages.', 'and the list says "Showing matches from all pages."' + tag, m.note);
  const firsts = [];
  for(const t of FIX.tables){
    await page.fill(`${pane} [data-q]`, t.rows[0].generic);
    const got = await page.$$eval(`${pane} tr[data-ref]`, x => x.map(e => e.dataset.ref));
    const want = expectRows(FIX.tables, BDK_OPT.searchFields, t.rows[0].generic).map(r => { const [id, i] = r.split(':'); return FIX.tables.findIndex(u => String(u.id) === id) + ':' + i; });
    if(!got.includes(FIX.tables.indexOf(t) + ':0') || JSON.stringify(got) !== JSON.stringify(want)) firsts.push(`${t.id} ${t.rows[0].generic}`);
  }
  check(!firsts.length, `the first drug of each of the ${FIX.tables.length} pages is found on its page, with exactly the rows whose searched fields hold it` + tag, firsts);
  for(const [term, field] of [['NSAID', 'category'], ['CS-II', 'classification'], ['Pseudomonas', 'activity'], ['QTc', 'essential']]){
    await page.fill(`${pane} [data-q]`, term);
    const got = await page.$$eval(`${pane} tr[data-ref]`, x => x.length);
    const want = expectRows(FIX.tables, BDK_OPT.searchFields, term).length;
    check(got === want && want > 0, `"${term}" (in ${field}) finds its ${want} rows` + tag, got);
  }
  await page.fill(`${pane} [data-q]`, 'zzqx no such drug');
  check(await page.$eval(`${pane} [data-body]`, b => !b.querySelector('tr') && (b.querySelector('[data-nomatch]') || {}).textContent === 'No matches'), '"No matches" when nothing matches' + tag);
  await page.click(`${pane} [data-listgroup="-1"]`);
  await page.fill(`${pane} [data-q]`, 'methadone');
  check(await page.$eval(`${pane} [data-body]`, b => !b.querySelector('[data-allnote]')), 'with All pages chosen the search does not say so' + tag);

  // the detail row: click, Enter, Space; methadone's sections
  const mref = FIX.tables.findIndex(t => t.id === 25) + ':' + FIX.tables.find(t => t.id === 25).rows.findIndex(r => r.generic.startsWith('methadone'));
  const tr = `${pane} tr[data-ref="${mref}"]`;
  const isOpen = () => page.$eval(tr, t => !!(t.nextElementSibling && t.nextElementSibling.classList.contains('detail')));
  await page.click(`${tr} td:nth-child(2)`);
  const det = await page.$eval(tr, t => { const d = t.nextElementSibling; return {cls: d.className, colspan: d.firstElementChild.colSpan,
    secs: [...d.querySelectorAll('.eksec')].map(s => ({h: s.querySelector('h4').textContent, warn: s.classList.contains('bwsec'),
      li: [...s.querySelectorAll('li')].map(l => ({q: (l.querySelector('.qual') || {}).textContent || '', t: l.textContent}))}))}; });
  check(det.cls === 'detail' && det.colspan === 5, 'a click on a row opens its detail row under it' + tag, det);
  const ms = det.secs;
  check(ms.length === 2 && ms[0].h === 'Key side effects' && ms[1].h === '⚠ US boxed warnings' && ms[1].warn,
        'methadone\'s detail: Key side effects, then ⚠ US boxed warnings marked as a warning' + tag, ms.map(s => s.h));
  check(ms[1] && ms[1].li.length === 2 && ms[1].li[0].q === 'all opioid analgesics' && ms[1].li[0].t.startsWith('all opioid analgesics risk of opioid addiction, abuse, and misuse which can lead to overdose and death; serious, life-threatening, or fatal respiratory depression may occur') &&
        ms[1].li[1].q === 'only for methadone' && ms[1].li[1].t.startsWith('only for methadone QTc interval prolongation and serious arrhythmia (Torsades de Pointes)'),
        'its two boxed warnings, each with its qualifier; "See above" shows page 25\'s list, as BDK\'s resolveSeeAbove does' + tag, ms[1]);
  check(ms[0] && ms[0].li.length === 1 && ms[0].li[0].t === 'dizziness, drowsiness, nausea, vomiting, constipation, respiratory depression (dose-related), QTc prolongation', 'its key side effects as the list prints them' + tag, ms[0]);
  const mSecs = JSON.stringify(ms.flatMap(s => s.li.map(l => KIND[s.h.startsWith('Key') ? 0 : s.h.includes('boxed') ? 1 : 2] + (l.q ? ' ' + l.q : ''))).sort());
  check(mSecs === JSON.stringify(BDK_SECTIONS['25:5']), 'the sections and qualifiers BDK gives methadone' + tag, mSecs);
  check(!(await sideways(page)), 'no sideways scroll with a detail open' + tag);
  await page.click(`${tr} td:nth-child(2)`);
  check(!(await isOpen()), 'a second click closes it' + tag);
  await page.focus(tr); await page.keyboard.press('Enter');
  check(await isOpen(), 'Enter on the row opens it' + tag);
  await page.keyboard.press('Enter');
  check(!(await isOpen()), 'Enter again closes it' + tag);
  await page.keyboard.press(' ');
  check(await isOpen(), 'Space opens it too' + tag);
  await page.keyboard.press(' ');
  const t14 = FIX.tables.findIndex(t => t.id === 14), d14 = FIX.tables[t14].rows.findIndex(r => r.generic === 'diclofenac (PO)');
  await page.fill(`${pane} [data-q]`, 'diclofenac (PO)');
  await page.click(`${pane} tr[data-ref="${t14}:${d14}"] td:nth-child(2)`);
  const dic = await page.$eval(`${pane} tr[data-ref="${t14}:${d14}"] + tr.detail`, d => [...d.querySelectorAll('.eksec')].map(s => ({h: s.querySelector('h4').textContent,
    q: [...s.querySelectorAll('li')].map(l => (l.querySelector('.qual') || {}).textContent || '')})));
  check(JSON.stringify(dic) === JSON.stringify([{h: 'Key side effects', q: ['']}, {h: '⚠ US boxed warnings', q: ['']}, {h: 'Other notes', q: ['']}]),
        'diclofenac (PO): its three sections, without the warning the list qualifies "(only for ketorolac)"' + tag, dic);
  const emptyAt = FIX.tables.flatMap((t, ti) => t.rows.map((r, i) => [ti, i, r])).find(([, , r]) => !r.essential);
  await page.fill(`${pane} [data-q]`, emptyAt[2].generic);
  await page.click(`${pane} tr[data-ref="${emptyAt[0]}:${emptyAt[1]}"] td:nth-child(2)`);
  check(await page.$eval(`${pane} tr[data-ref="${emptyAt[0]}:${emptyAt[1]}"] + tr.detail`, d => { const c = d.cloneNode(true); c.querySelectorAll('[data-ct-compare]').forEach(b => b.remove()); return c.textContent.trim(); }) === 'No essential knowledge listed.',
        `a row with no essential knowledge (${emptyAt[2].generic}) says so` + tag);

  // every row's sections, against what BDK's own cards give it
  const all = await page.evaluate(K => { const A = FX.api('drug-list-tab'), out = {};
    DRUG_TABLES.forEach((t, ti) => t.rows.forEach((r, i) => { out[t.id + ':' + i] = A.parts(t, i).parts.map(p => K[p.k] + (p.qual ? ' ' + p.qual : '')).filter((x, j, a) => a.indexOf(x) === j).sort(); }));
    return out; }, KIND);
  const off = Object.keys(BDK_SECTIONS).filter(k => JSON.stringify(all[k]) !== JSON.stringify(BDK_SECTIONS[k]));
  check(Object.keys(all).length === Object.keys(BDK_SECTIONS).length && !off.length, `all ${Object.keys(BDK_SECTIONS).length} rows: the detail's sections and qualifiers are the ones BDK's cards give each row` + tag, off.slice(0, 5).map(k => `${k}: ${JSON.stringify(all[k])} vs ${JSON.stringify(BDK_SECTIONS[k])}`));

  // every row's sections with their text, against the sections worked out apart (expectedSections)
  const content = await page.evaluate(K => { const A = FX.api('drug-list-tab'), out = {};
    DRUG_TABLES.forEach((t, ti) => t.rows.forEach((r, i) => { out[t.id + ':' + i] = A.parts(t, i).parts.map(p => ({kind: K[p.k], qual: p.qual, text: p.text})); }));
    return out; }, KIND);
  const exp = expectedSections(FIX.tables);
  const offC = Object.keys(exp).filter(k => JSON.stringify(content[k]) !== JSON.stringify(exp[k]));
  check(Object.keys(content).length === 300 && !offC.length, 'all 300 rows: each section\'s text is the list\'s, with "See above" resolved as BDK\'s resolveSeeAbove does' + tag, offC.slice(0, 3));
  // the four rows BDK resolves, against BDK's own result (BDK_SEE_ABOVE, from its cards)
  const seeBad = Object.keys(BDK_SEE_ABOVE).filter(k => {
    const bdk = BDK_SEE_ABOVE[k].filter(x => x.startsWith('(all opioid analgesics) ')).map(x => x.slice(24));
    const kit = (content[k] || []).filter(p => p.kind === 'bw' && p.qual === 'all opioid analgesics').flatMap(p => splitItems(p.text));
    const w4 = x => x.toLowerCase().split(/\s+/).slice(0, 4).join(' ');
    return !bdk.length || kit.length !== bdk.length || kit.some((x, j) => w4(x) !== w4(bdk[j])) || (content[k] || []).some(p => /^See above/i.test(p.text));
  });
  check(Object.keys(BDK_SEE_ABOVE).length === 4 && !seeBad.length, `the ${Object.keys(BDK_SEE_ABOVE).length} rows BDK resolves (${Object.keys(BDK_SEE_ABOVE).join(', ')}): the same ${BDK_SEE_ABOVE['25:5'].filter(x => x.startsWith('(all')).length} opioid warnings as BDK's resolved list, item for item (its cards reword them)` + tag, seeBad);
  // page 26 with Week 10 chosen: page 25 is not on screen
  const wk10 = FIX.groups.findIndex(g => g.label === 'Week 10');
  await page.fill(`${pane} [data-q]`, '');
  await page.click(`${pane} [data-listgroup="${wk10}"]`);
  const t26 = FIX.tables.findIndex(t => t.id === 26);
  await page.click(`${pane} tr[data-ref="${t26}:0"] td:nth-child(2)`);
  const p26 = await page.$eval(`${pane} tr[data-ref="${t26}:0"] + tr.detail`, d => [...d.querySelectorAll('.bwsec li')].map(l => l.textContent));
  check(JSON.stringify(await shownIds(page)) === JSON.stringify(['16', '26', '27']) && p26.length === 2 && p26[0].startsWith('all opioid analgesics ' + 'risk of opioid addiction, abuse, and misuse which can lead to overdose and death; serious, life-threatening, or fatal respiratory depression may occur') &&
        p26[1].startsWith('use with CYP3A4 inhibitors'), 'Week 10 (pages 16, 26, 27): hydrocodone and acetaminophen (p26) shows page 25\'s opioid warnings for its "See above"' + tag, p26);
  await page.click(`${pane} [data-listgroup="-1"]`);

  // nothing stored
  await page.evaluate(() => show('topics'));
  await page.click(`#nav button[data-v="${BDK_OPT.tab}"]`);
  const after = await snapshot(page);
  /* The core's own place record (views.js placeSave: sessionStorage <NS>:place, the open
     tab and the line at the top of the screen, so a reload comes back to it) is written
     for every tab, the core's own included; it is the one write allowed, and only in
     the core's shape. Everything else must be as it was before the tab opened. */
  const {writes, placeKey, place} = await page.evaluate(() => ({writes: window.__writes, placeKey: PLACE_KEY, place: sessionStorage.getItem(PLACE_KEY)}));
  const B = JSON.parse(before), A = JSON.parse(after);
  const placeOk = place === null || (() => { const p = JSON.parse(place); return JSON.stringify(Object.keys(p).sort()) === JSON.stringify(['a', 'at', 'open', 'v', 'y']) && p.v === BDK_OPT.tab; })();
  delete A.ss[placeKey]; delete B.ss[placeKey];
  const other = writes.filter(w => !(w[0] === 'setItem' && w[1] === 'ss' && w[2] === placeKey));
  check(!other.length && JSON.stringify(A) === JSON.stringify(B) && placeOk,
        'nothing written to localStorage, sessionStorage, IndexedDB or the progress (DB), apart from the core\'s place record' + tag,
        {other, placeOk, same: JSON.stringify(A) === JSON.stringify(B)});
  check(JSON.stringify(await shownIds(page)) === JSON.stringify(FIX.tables.map(t => String(t.id))), 'the chosen group lasts for the visit: back on the tab, All pages is still chosen' + tag);
  const fxErr = await page.evaluate(() => FX.errors.slice());
  const cAll = cerr.concat(await page.evaluate(() => window.__cerr || []));
  check(!errors.length && !fxErr.length, 'no page error and no module error' + tag, errors.concat(fxErr.map(e => JSON.stringify(e))).slice(0, 3));
  check(!cAll.length, 'no console error' + tag, cAll.slice(0, 3));
  await ctx.close();
  return after;
}

/* the storage check of a page (see bdkView): the core's own place record is the one write allowed */
async function storageCheck(page, before, tab, label){
  const after = await snapshot(page);
  const {writes, placeKey, place} = await page.evaluate(() => ({writes: window.__writes, placeKey: PLACE_KEY, place: sessionStorage.getItem(PLACE_KEY)}));
  const B = JSON.parse(before), A = JSON.parse(after);
  const placeOk = place === null || (() => { const p = JSON.parse(place); return JSON.stringify(Object.keys(p).sort()) === JSON.stringify(['a', 'at', 'open', 'v', 'y']) && p.v === tab; })();
  delete A.ss[placeKey]; delete B.ss[placeKey];
  const other = writes.filter(w => !(w[0] === 'setItem' && w[1] === 'ss' && w[2] === placeKey));
  check(!other.length && JSON.stringify(A) === JSON.stringify(B) && placeOk, label, {other, placeOk, same: JSON.stringify(A) === JSON.stringify(B)});
}

/* recall mode (DEENT src/druglist_ui.js at 0281922, lines 31-32, 160-174, 203-209, 236, 248-259) */
async function recallView(browser, file, width){
  const tag = ` (recall, ${width} px)`;
  const {ctx, page, errors} = await L.openPage(browser, file, {viewport: {width, height: 900}}, consoleTrap);
  const cerr = []; page.on('console', m => { if(m.type() === 'error') cerr.push(m.text()); });
  const before = await snapshot(page);
  await page.evaluate(() => { window.__writes = []; });
  await page.click(`#nav button[data-v="${BDK_OPT.tab}"]`);
  const off = await page.evaluate(p => ({pressed: document.querySelector(p + ' [data-dl="recall"]').getAttribute('aria-pressed'),
    hid: document.querySelectorAll(p + ' td[data-hidden]').length, rows: document.querySelectorAll(p + ' tr.dlt-recall').length,
    note: !!document.querySelector(p + ' [data-recallnote]'), extra: document.querySelectorAll(p + ' [data-dl="revealall"], ' + p + ' [data-dl="showcls"]').length}), pane);
  check(off.pressed === 'false' && !off.hid && !off.rows && !off.note && !off.extra, 'recall mode is off by default (recallDefault false): no hidden cell, no writing box, no recall buttons' + tag, off);
  await page.click(`${pane} [data-dl="recall"]`);
  check(await page.$eval(`${pane} [data-recallnote]`, e => e.textContent) === 'Recall mode: each row shows the drug only. Write what you recall, then Reveal and compare. This is a self-check: what you type is not graded and not saved, and it is gone when the page reloads. The search looks only in the fields shown and in the class, so searching by class shows which drugs are in that class.', 'the Recall mode chip turns it on, with its note' + tag);
  check(await page.$eval(`${pane} [data-q]`, e => e.placeholder) === 'Search generic, brand, category…', 'in recall mode the search box names only what it searches (recallPlaceholder)' + tag);
  check(JSON.stringify(await shownIds(page)) === JSON.stringify(['5', '9']), 'the group stays as chosen' + tag);
  // what each shown row holds: recallShow fields as written, every other cell empty but for "hidden", no hidden text anywhere in the DOM
  const look = () => page.evaluate(([p, cols, show]) => {
    const out = {bad: [], leak: [], n: 0, hidden: 0};
    const pn = document.querySelector(p), body = pn.querySelector('[data-body]'), text = pn.innerHTML;
    const attrs = [...pn.querySelectorAll('*')].flatMap(e => [...e.attributes].map(a => a.value));
    for(const tr of body.querySelectorAll('tr[data-ref]')){
      const [ti, i] = tr.dataset.ref.split(':').map(Number), r = DRUG_TABLES[ti].rows[i], cells = [...tr.children];
      out.n++;
      const visible = new Set(show.map(f => String(r[f] || '')));
      cols.forEach((c, k) => {
        const td = cells[k];
        if(show.includes(c[0])){ if(!td.textContent.includes(String(r[c[0]] || ''))) out.bad.push(tr.dataset.ref + ' ' + c[0]); }
        else {
          out.hidden++;
          if(td.dataset.hidden !== '1' || td.textContent !== 'hidden') out.bad.push(tr.dataset.ref + ' ' + c[0] + ': ' + td.textContent.slice(0, 40));
        }
      });
      const det = tr.parentElement.querySelector(`tr.detail[data-for="${tr.dataset.ref}"]`);
      if(!det || det.textContent.trim() || !det.hidden) out.bad.push(tr.dataset.ref + ' detail');
      const inPage = v => text.includes(v.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;')) || attrs.some(a => a.includes(v));
      for(const f of ['essential', 'indication', 'activity', 'category', 'classification']){
        const v = String(r[f] || '');
        if(v.length >= 6 && !show.includes(f) && ![...visible].some(x => x.includes(v)) && inPage(v)) out.leak.push(tr.dataset.ref + ' ' + f);
      }
      // each section of the row's detail, as the module splits it (and resolves "See above")
      for(const sct of FX.api('drug-list-tab').parts(DRUG_TABLES[ti], i).parts){
        const v = String(sct.text || '');
        if(v.length >= 12 && ![...visible].some(x => x.includes(v)) && inPage(v)) out.leak.push(tr.dataset.ref + ' section: ' + v.slice(0, 30));
      }
    }
    return out;
  }, [pane, BDK_OPT.columns, BDK_OPT.recallShow]);
  const N14 = FIX.tables.filter(t => [5, 9].includes(t.id)).reduce((n, t) => n + t.rows.length, 0);
  let o = await look();
  check(o.n === N14 && !o.bad.length && o.hidden === o.n * 3, `each of the ${o.n} rows shows only its ${BDK_OPT.recallShow.join(' and ')}; the other ${o.hidden} cells say only "hidden", and every detail row is empty` + tag, o.bad.slice(0, 4));
  check(!o.leak.length, 'no hidden field\'s text, and no section of the hidden detail, is anywhere in the list\'s DOM, attributes included' + tag, o.leak.slice(0, 4));
  const rowsOn = await page.$$eval(`${pane} tr[data-ref]`, t => t.map(tr => [tr.getAttribute('tabindex'), getComputedStyle(tr).cursor]));
  check(rowsOn.length && rowsOn.every(([t, c]) => t === null && c !== 'pointer'), 'in recall mode drug rows take no focus and no pointer cursor (Reveal is the control)' + tag, rowsOn.slice(0, 2));
  const r0 = (await page.$$eval(`${pane} tr[data-ref]`, t => t.map(x => x.dataset.ref)))[0], r1 = (await page.$$eval(`${pane} tr[data-ref]`, t => t.map(x => x.dataset.ref)))[1];
  await page.click(`${pane} tr[data-ref="${r0}"] td:nth-child(2)`);
  check(await page.$eval(`${pane} tr[data-ref="${r0}"]`, tr => tr.nextElementSibling.classList.contains('dlt-recall') &&
        ![...tr.closest('[data-body]').querySelectorAll('tr.detail')].some(d => d.textContent.trim())), 'in recall mode a tap on the row does not open it' + tag);
  // Reveal: that row's cells and detail, and only that row's
  const rowState = ref => page.evaluate(([p, ref]) => { const tr = document.querySelector(`${p} tr[data-ref="${ref}"]`), b = document.querySelector(`${p} [data-reveal="${ref}"]`),
    d = document.querySelector(`${p} tr.detail[data-for="${ref}"]`), [ti, i] = ref.split(':').map(Number), r = DRUG_TABLES[ti].rows[i];
    return {hidden: tr.querySelectorAll('td[data-hidden]').length, cat: tr.children[0].textContent === r.category, text: b.textContent, exp: b.getAttribute('aria-expanded'),
      ctl: b.getAttribute('aria-controls').split(' ').every(id => !!document.getElementById(id)) && b.getAttribute('aria-controls').split(' ').length === 2,
      det: !d.hidden && !!d.querySelector('.ekbox, .dlt-note'), focus: document.activeElement === b}; }, [pane, ref]);
  await page.click(`${pane} [data-reveal="${r0}"]`);
  let a = await rowState(r0), b = await rowState(r1);
  check(!a.hidden && a.cat && a.det && a.text === 'Hide again' && a.exp === 'true' && a.ctl && a.focus, 'Reveal shows that row\'s cells and its detail; the button reads Hide again, aria-expanded true, aria-controls naming the row and its detail, and keeps the focus' + tag, a);
  const only = JSON.stringify(await page.evaluate(() => FX.api('drug-list-tab').state().revealed));
  await page.click(`${pane} [data-listgroup="${FIX.groups.findIndex(g => g.label === 'Week 14')}"]`);
  const openRows = await page.$$eval(`${pane} tr[data-ref]`, t => t.filter(tr => !tr.querySelector('td[data-hidden]')).map(tr => tr.dataset.ref));
  check(b.hidden === 3 && !b.det && only === JSON.stringify([r0]) && JSON.stringify(openRows) === JSON.stringify([r0]), 'and only that row: the next row stays hidden, and after a redraw only that row is open' + tag, {b, only, openRows});
  await page.focus(`${pane} [data-reveal="${r0}"]`);
  await page.click(`${pane} [data-reveal="${r0}"]`);
  a = await rowState(r0);
  check(a.hidden === 3 && !a.det && a.text === 'Reveal' && a.exp === 'false' && a.focus, 'Hide again hides it again' + tag, a);
  await page.keyboard.press('Enter');
  a = await rowState(r0);
  check(!a.hidden && a.det && a.focus, 'Enter on Reveal reveals' + tag, a);
  await page.keyboard.press(' ');
  a = await rowState(r0);
  check(a.hidden === 3 && !a.det, 'Space on Hide again hides' + tag, a);
  // Show class
  await page.click(`${pane} [data-dl="showcls"]`);
  const cls = await page.evaluate(p => [...document.querySelectorAll(p + ' tr[data-ref]')].map(tr => { const [ti, i] = tr.dataset.ref.split(':').map(Number);
    return tr.children[0].textContent === DRUG_TABLES[ti].rows[i].category && tr.querySelectorAll('td[data-hidden]').length === 2; }), pane);
  check(cls.length === N14 && cls.every(Boolean), `Show class shows every row's ${BDK_OPT.recallClassField} and nothing else` + tag, cls);
  await page.click(`${pane} [data-dl="showcls"]`);
  check(await page.$$eval(`${pane} tr[data-ref]`, t => t.every(tr => tr.querySelectorAll('td[data-hidden]').length === 3)), 'Show class again hides the class' + tag);
  // typed text: kept through a group change and a search, for the visit
  await page.fill(`${pane} textarea[data-typed="${r1}"]`, 'beta blocker, my guess');
  await page.click(`${pane} [data-listgroup="-1"]`);
  const g1 = await page.$eval(`${pane} textarea[data-typed="${r1}"]`, t => t.value);
  await page.click(`${pane} [data-listgroup="${FIX.groups.findIndex(g => g.label === 'Week 14')}"]`);
  await page.fill(`${pane} [data-q]`, 'NSAID');
  const nsaid = await page.$$eval(`${pane} tr[data-ref]`, t => t.length);
  check(nsaid === expectRows(FIX.tables, RECALL_FIELDS, 'NSAID').length && nsaid > 0, `in recall mode the search looks in the class field too, as DEENT's does: "NSAID" (a category) finds its ${nsaid} rows` + tag);
  await page.fill(`${pane} [data-q]`, 'QTc');
  const qtcOn = await page.$$eval(`${pane} tr[data-ref]`, t => t.length);
  check(qtcOn === 0 && expectRows(FIX.tables, RECALL_FIELDS, 'QTc').length === 0 && expectRows(FIX.tables, BDK_OPT.searchFields, 'QTc').length > 0 &&
        await page.$eval(`${pane} [data-body]`, b => !!b.querySelector('[data-nomatch]')),
        `in recall mode the search looks only in ${RECALL_FIELDS.join(', ')}: "QTc", in hidden fields only, finds nothing` + tag, qtcOn);
  await page.fill(`${pane} [data-q]`, 'NSAID');
  check(await page.$$eval(`${pane} tr[data-ref]`, t => t.every(tr => tr.querySelectorAll('td[data-hidden]').length === 3)), 'and the rows found stay hidden' + tag);
  await page.fill(`${pane} [data-q]`, '');
  const g2 = await page.$eval(`${pane} textarea[data-typed="${r1}"]`, t => t.value);
  check(g1 === 'beta blocker, my guess' && g2 === g1, 'what is typed is kept through a group change and a search' + tag, {g1, g2});
  // Reveal all shown honours the group and the search; Hide all
  const revealed = () => page.evaluate(() => FX.api('drug-list-tab').state().revealed.sort());
  await page.click(`${pane} [data-dl="revealall"]`);
  const wk = await page.$$eval(`${pane} tr[data-ref]`, t => t.map(x => x.dataset.ref).sort());
  check(JSON.stringify(await revealed()) === JSON.stringify(wk) && await page.$$eval(`${pane} tr[data-ref]`, t => t.every(tr => !tr.querySelector('td[data-hidden]'))),
        `Reveal all shown reveals the ${wk.length} rows of the chosen group` + tag);
  await page.click(`${pane} [data-listgroup="-1"]`);
  const others = await page.$$eval(`${pane} tr[data-ref]`, t => t.filter(tr => !!tr.querySelector('td[data-hidden]')).length);
  check(others === FIX.tables.reduce((n, t) => n + t.rows.length, 0) - wk.length, 'and no row outside it' + tag, others);
  await page.click(`${pane} [data-dl="hideall"]`);
  check(!(await revealed()).length && await page.$$eval(`${pane} tr[data-ref]`, t => t.every(tr => tr.querySelectorAll('td[data-hidden]').length === 3)), 'Hide all hides every row' + tag);
  await page.fill(`${pane} [data-q]`, 'NSAID');
  await page.click(`${pane} [data-dl="revealall"]`);
  const want = expectRows(FIX.tables, RECALL_FIELDS, 'NSAID').map(r => { const [id, i] = r.split(':'); return FIX.tables.findIndex(u => String(u.id) === id) + ':' + i; }).sort();
  check(JSON.stringify(await revealed()) === JSON.stringify(want), `with a search, Reveal all shown reveals exactly the ${want.length} rows found` + tag);
  check(!(await sideways(page)), 'no sideways scroll in recall mode with rows revealed' + tag);
  await page.click(`${pane} [data-dl="hideall"]`);
  check(!(await revealed()).length, 'Hide all again' + tag);
  await page.fill(`${pane} [data-q]`, '');
  check(!(await sideways(page)), 'no sideways scroll in recall mode with every table shown' + tag);
  await page.click(`${pane} [data-dl="recall"]`);
  check(!(await page.$(`${pane} td[data-hidden]`)) && !(await page.$(`${pane} tr.dlt-recall`)), 'Recall mode off shows every cell again' + tag);
  await page.fill(`${pane} [data-q]`, 'QTc');
  const qtcOff = await page.$$eval(`${pane} tr[data-ref]`, t => t.length);
  check(qtcOff === expectRows(FIX.tables, BDK_OPT.searchFields, 'QTc').length && qtcOff > 0, `with recall off the search looks in searchFields again: "QTc" finds its ${qtcOff} rows` + tag);
  const rowsOff = await page.$$eval(`${pane} tr[data-ref]`, t => t.map(tr => [tr.getAttribute('tabindex'), getComputedStyle(tr).cursor]));
  check(rowsOff.every(([t, c]) => t === '0' && c === 'pointer'), 'with recall off drug rows take the focus and a pointer cursor again' + tag, rowsOff.slice(0, 2));
  await page.fill(`${pane} [data-q]`, '');
  await storageCheck(page, before, BDK_OPT.tab, 'recall mode: nothing written to localStorage, sessionStorage, IndexedDB or the progress (DB), apart from the core\'s place record' + tag);
  const cAll = cerr.concat(await page.evaluate(() => window.__cerr || [])), fxErr = await page.evaluate(() => FX.errors.length);
  check(!errors.length && !cAll.length && !fxErr, 'no page, console or module error in recall mode' + tag, errors.concat(cAll).slice(0, 3));
  // a reload: what was typed is gone
  await page.reload();
  await page.waitForFunction(() => document.querySelectorAll('#nav button').length > 3);
  await page.click(`#nav button[data-v="${BDK_OPT.tab}"]`).catch(() => {});
  await page.evaluate(t => show(t), BDK_OPT.tab);
  await page.click(`${pane} [data-dl="recall"]`);
  await page.click(`${pane} [data-listgroup="${FIX.groups.findIndex(g => g.label === 'Week 14')}"]`);
  const after = await page.$eval(`${pane} textarea[data-typed="${r1}"]`, t => t.value);
  check(after === '' && !(await revealed()).length, 'after a reload what was typed is gone and nothing is revealed' + tag, after);
  await ctx.close();
}

async function optionView(browser, file, o){
  const {ctx, page, errors} = await L.openPage(browser, file, {viewport: {width: 390, height: 900}}, consoleTrap);
  const PX = Buffer.from('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNkYAAAAAYAAjCB0C8AAAAASUVORK5CYII=', 'base64');
  const asked = [];
  await page.route('**/pages/*.webp', r => { asked.push(new URL(r.request().url()).pathname.split('/').pop()); r.fulfill({status: 200, contentType: 'image/png', body: PX}); });
  const cerr = []; page.on('console', m => { if(m.type() === 'error') cerr.push(m.text()); });
  const p = '#v-' + o.tab;
  const nav = await page.$(`#nav button[data-v="${o.tab}"]`);
  check(!!nav && (await nav.textContent()) === o.label && !(await page.$(`#nav button[data-v="${BDK_OPT.tab}"]`)), `options: the tab is "${o.label}" at #v-${o.tab}`);
  await nav.click();
  const rc = await page.evaluate(p => [...document.querySelectorAll(p + ' tr[data-ref]')].slice(0, 30).map(tr => [...tr.children].map(td => td.dataset.hidden === '1' ? 'H' : 'V').join('')), p);
  check(await page.$eval(`${p} [data-dl="recall"]`, b => b.getAttribute('aria-pressed')) === 'true' && rc.length && rc.every(x => x === 'HV'),
        `options: recallDefault true opens in recall mode, and recallShow ['label'] keeps only the Listed as column visible`, rc.slice(0, 3));
  check(!(await page.$(`${p} [data-dl="showcls"]`)) && !!(await page.$(`${p} [data-dl="revealall"]`)), 'options: recallClassField empty, no Show class chip');
  // a shown column's sub-field (here BDK's activity under Listed as) stays hidden until Reveal: it is not in recallShow
  const actAt = (() => { for(const [ti, t] of FIX.tables.entries()) for(const [i, r] of t.rows.entries()) if(r.activity) return {ref: `${ti}:${i}`, text: r.activity}; return null; })();
  if(!actAt) check(false, 'BDK\'s tables hold a row with activity text');
  else {
    const before = await page.evaluate(([p, a]) => { const pane = document.querySelector(p); return {inPage: pane.innerHTML.includes(a.text) || pane.textContent.includes(a.text), row: !!pane.querySelector(`tr[data-ref="${a.ref}"]`)}; }, [p, actAt]);
    await page.click(`${p} [data-reveal="${actAt.ref}"]`);
    const after = await page.evaluate(([p, a]) => { const tr = document.querySelector(`${p} tr[data-ref="${a.ref}"]`); return !!tr && tr.textContent.includes(a.text); }, [p, actAt]);
    check(before.row && !before.inPage && after, `in recall mode a shown column's sub-field is hidden until Reveal (activity of row ${actAt.ref}: absent from the page before, in its row after)`, {before, after});
    const gone = () => page.evaluate(([p, a]) => { const pane = document.querySelector(p); return !(pane.innerHTML.includes(a.text) || pane.textContent.includes(a.text)); }, [p, actAt]);
    await page.click(`${p} [data-reveal="${actAt.ref}"]`);   // Hide again
    const afterHide = await gone();
    await page.click(`${p} [data-reveal="${actAt.ref}"]`);   // Reveal once more
    const shownAgain = !(await gone());
    await page.click(`${p} [data-dl="hideall"]`);
    const afterAll = await gone();
    check(afterHide && shownAgain && afterAll, 'and it is gone from the page again after Hide again, and after Hide all', {afterHide, shownAgain, afterAll});
  }
  check(!(await page.$(`${p} [data-listview]`)) && !(await page.$(`${p} .pdfpage`)) && (await page.$$(`${p} section[data-table] table`)).length === FIX.tables.length,
        'recall mode draws the table only: no Table / page-image choice while it is on');
  await page.click(`${p} [data-dl="recall"]`);
  check(!(await page.$(`${p} [data-listgroup]`)), 'options: no groups, no chips');
  const ids = await page.$$eval(`${p} [data-body] section[data-table]`, s => s.map(e => e.dataset.table));
  check(JSON.stringify(ids) === JSON.stringify(FIX.tables.map(t => String(t.id))), 'options: with no default group the tab opens on every table');
  const th = await page.$$eval(`${p} section[data-table] thead tr`, r => r.map(x => [...x.children].map(c => c.textContent).join('|')));
  check(th.length === FIX.tables.length && th.every(h => h === o.columns.map(c => c[1]).join('|')), 'options change the columns: ' + o.columns.map(c => c[1]).join(', '), th[0]);
  const r0 = await page.$eval(`${p} tr[data-ref="0:0"]`, tr => [...tr.children].map(td => td.textContent));
  check(JSON.stringify(r0) === JSON.stringify(o.columns.map(c => FIX.tables[0].rows[0][c[0]])), 'and each cell holds its column\'s field', r0);
  await page.fill(`${p} [data-q]`, 'NSAID');
  const nsaid = await page.$$eval(`${p} tr[data-ref]`, x => x.length);
  await page.fill(`${p} [data-q]`, 'ibuprofen');
  const ibu = await page.$$eval(`${p} tr[data-ref]`, x => x.length);
  check(nsaid === 0 && ibu === expectRows(FIX.tables, o.searchFields, 'ibuprofen').length && ibu > 0, `options change the searched fields: "NSAID" (a category) finds nothing when only ${o.searchFields.join(', ')} is searched; "ibuprofen" finds its ${ibu} row(s)`, {nsaid, ibu});
  await page.click(`${p} tr[data-ref] td`);
  check(await page.$eval(`${p} tr.detail td`, td => td.colSpan) === o.columns.length, 'the detail row spans the columns the options give');
  const seg = await page.$$eval(`${p} [data-listview] button`, b => b.map(x => x.textContent));
  check(JSON.stringify(seg) === JSON.stringify(['Table', o.imageLabel]), `every table gives an image: the view choice Table / ${o.imageLabel} is offered`, seg);
  await page.click(`${p} [data-listview] [data-val="image"]`);
  const imgs = await page.$$eval(`${p} .pdfpage img`, x => x.map(i => [i.getAttribute('src'), i.getAttribute('width'), i.getAttribute('height'), i.getAttribute('alt')]));
  const wantImg = FIX.tables.map(t => [`pages/p${t.id}.webp`, String(BDK_PAGE_IMG[t.id][0]), String(BDK_PAGE_IMG[t.id][1]), `${o.imageLabel} ${t.id}: ${t.title}`]);
  check(JSON.stringify(imgs) === JSON.stringify(wantImg), `the image view shows each table's image, at its size, one per table (${imgs.length})`, imgs.slice(0, 2));
  check(!(await page.$(`${p} [data-q]`)) && !(await page.$(`${p} tr[data-ref]`)), 'the image view has no table and no search box');
  await page.click(`${p} [data-dl="recall"]`);
  check(!(await page.$(`${p} [data-listview]`)) && !(await page.$(`${p} .pdfpage`)) && (await page.$$(`${p} section[data-table] table`)).length === FIX.tables.length &&
        (await page.$$(`${p} td[data-hidden]`)).length > 0, 'Recall mode from the image view: the tables, hidden, and no view choice');
  await page.click(`${p} [data-dl="recall"]`);
  check(JSON.stringify(await page.$$eval(`${p} [data-listview] button`, b => b.map(x => x.getAttribute('aria-pressed')))) === JSON.stringify(['false', 'true']) &&
        (await page.$$(`${p} .pdfpage img`)).length === FIX.tables.length, 'Recall mode off: the choice is back, on the image view chosen before');
  check(!(await sideways(page)), 'no sideways scroll in the image view (390 px)');
  await page.click(`${p} [data-listview] [data-val="table"]`);
  check((await page.$$(`${p} section[data-table] table`)).length === FIX.tables.length, 'Table brings the tables back');
  check(!errors.length && !cerr.length && !(await page.evaluate(() => FX.errors.length + (window.__cerr || []).length)), 'no page or console error (options copy)', errors.concat(cerr).slice(0, 3));
  await ctx.close();
}


/* ---------- v2: ratings kept in the progress (DB.drugs) ---------- */
const V2_FIELDS = [['indication', 'Common indications'], ['essential', 'Essential knowledge']];
const V2_OPT = opts(Object.assign({}, BDK_OPT, {recallFields: V2_FIELDS}));
const slugOf = s => String(s == null ? '' : s).toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
const ID0 = slugOf(FIX.tables[0].rows[0].generic), ID1 = slugOf(FIX.tables[0].rows[1].generic);
/* the template bank's first two multiple-choice questions, mapped to BDK facts (template/q1_topics.js) */
const V2_FACTS = {'s1-1': [ID0 + ':indication'], 's1-2': [ID0 + ':indication', ID1 + ':essential']};
const dataFileV2 = (tables, facts) => dataFile(tables) + (facts ? `const DRUG_FACTS = ${JSON.stringify(facts)};\n` : '');
const buildV2 = (label, tables, o, facts) => L.scratchBuild(label, {files: {[FILE]: dataFileV2(tables, facts)},
  courseLine: `COURSE.files = (COURSE.files || ['atlas.js', 'diagrams.js', 'q1_topics.js']).concat([${JSON.stringify(FILE)}]);` + L.featureOn(__dirname, o)});
const v2Refuse = () => {
  const T = FIX.tables, dup = clone(T); dup[1].rows[0].generic = dup[0].rows[0].generic;
  return [
    ['recallFields naming a field no row has', 'v2nofield', T, opts(Object.assign({}, V2_OPT, {recallFields: [['schedule', 'Schedule']]})), null, /option recallFields names the field "schedule", which no row has/],
    ['recallFields naming a field recall mode keeps visible', 'v2shown', T, opts(Object.assign({}, V2_OPT, {recallFields: [['generic', 'Generic']]})), null, /option recallFields names "generic", which recall mode keeps visible/],
    ['recallFields entries that are not [field, name]', 'v2shape', T, opts(Object.assign({}, V2_OPT, {recallFields: ['indication']})), null, /option recallFields must be a list of \[field, name\] pairs/],
    ['two rows with the same id', 'v2dup', dup, V2_OPT, null, new RegExp(`table "2" row 1 and table "3" row 1 have the same id "${ID0}"`)],
    ['DRUG_FACTS naming a question the bank lacks', 'v2noq', T, V2_OPT, {'zz-9': [ID0 + ':indication']}, /DRUG_FACTS names the question "zz-9", which the bank does not have/],
    ['DRUG_FACTS naming a field recallFields lacks', 'v2nofact', T, V2_OPT, {'s1-1': [ID0 + ':brand']}, new RegExp(`DRUG_FACTS gives "s1-1" the fact "${ID0}:brand"`)],
  ];
};
const v2State = page => page.evaluate(() => ({ev: DB.drugs ? JSON.parse(JSON.stringify(DB.drugs.ev)) : null, v: DB.drugs ? DB.drugs.v : null,
  answers: DB.answers.length, qn: DB.qn || 0, log: LOG.length, profile: PROFILE,
  stored: (() => { try { const d = JSON.parse(localStorage.getItem(NS + ':data:' + PROFILE) || 'null'); return d && d.drugs ? d.drugs.ev : null; } catch(e){ return 'unreadable'; } })()}));
const v2Open = async (page, field) => {
  await page.click(`#nav button[data-v="${V2_OPT.tab}"]`);
  await page.click(`${pane} [data-listgroup="-1"]`);
  if(await page.$eval(`${pane} [data-dl="recall"]`, b => b.getAttribute('aria-pressed')) !== 'true') await page.click(`${pane} [data-dl="recall"]`);
  // only a different field is chosen: choosing the same one again would start the openings again
  if(field !== undefined && await page.$eval(`${pane} [data-dl="ask"]`, s => s.value) !== field) await page.selectOption(`${pane} [data-dl="ask"]`, field);
};
const statusOf = (page, ref) => page.$eval(`${pane} tr.dlt-recall[data-for="${ref}"] [data-status]`, p => p.textContent.replace(/\s+/g, ' ').trim()).catch(() => null);
const v2Reload = async page => { await page.reload(); await page.waitForFunction(() => document.querySelectorAll('#nav button').length > 3, null, {timeout: 15000}); };

async function v2View(browser, file, width){
  const tag = ` (${width} px)`;
  const {ctx, page, errors} = await L.openPage(browser, file, {viewport: {width, height: 900}}, consoleTrap);
  page.on('dialog', d => d.accept().catch(() => {}));
  const R0 = '0:0', R1 = '0:1', F0 = ID0 + ':indication';
  await v2Open(page);
  const opts0 = await page.$$eval(`${pane} [data-dl="ask"] option`, o => o.map(x => [x.value, x.textContent]));
  check(JSON.stringify(opts0) === JSON.stringify([['', 'Every hidden field']].concat(V2_FIELDS)), 'recall mode offers Ask for: every hidden field, then each of recallFields' + tag, opts0);
  check(!(await page.$(`${pane} [data-status]`)) && !(await page.$(`${pane} [data-rate]`)), 'with every hidden field asked, no rating and no status line (v1\'s recall mode)' + tag);
  await page.selectOption(`${pane} [data-dl="ask"]`, 'indication');
  let st = await v2State(page);
  check(st.ev === null && st.stored === null, 'asking for a field stores nothing' + tag, st);
  check(/^Common indications: not rated yet · bank questions: Not practised$/.test(await statusOf(page, R0) || ''),
        'the status line: not rated yet, and the two bank questions DRUG_FACTS maps to the fact: Not practised' + tag, await statusOf(page, R0));
  check(/^Common indications: not rated yet$/.test(await statusOf(page, '0:2') || ''), 'a fact no bank question tests shows no bank status' + tag, await statusOf(page, '0:2'));
  check(!(await page.$(`${pane} [data-rate="${R0}"]`)), 'no rating before Reveal' + tag);
  await page.click(`${pane} [data-reveal="${R0}"]`);
  const crit = await page.$$eval(`${pane} tr.dlt-recall[data-for="${R0}"] .dlo-crit li`, l => l.map(x => x.textContent));
  check(JSON.stringify(crit) === JSON.stringify(['Forgot: I could not produce it.', 'Partly: I had the idea but missed the key term or one part.', 'Knew: I wrote the key term without looking.']),
        'after Reveal: Forgot, Partly and Knew with DEENT\'s criteria' + tag, crit);
  await page.fill(`${pane} [data-typed="${R0}"]`, 'glaucoma, typed text');
  await page.click(`${pane} [data-rate="${R0}"][data-r="partly"]`);
  st = await v2State(page);
  check(st.ev && st.ev.length === 1 && st.ev[0].f === F0 && st.ev[0].r === 'partly' && typeof st.ev[0].at === 'number' && Object.keys(st.ev[0]).sort().join() === 'at,f,r' && st.v === 1,
        `Partly adds one rating {f: "${F0}", r: "partly", at} to DB.drugs (v 1), and nothing else` + tag, st.ev);
  check(st.answers === 0 && st.qn === 0 && st.log === 0, 'the rating is not an answer: DB.answers, the answer count and the answer history are unchanged (0, 0, 0)' + tag, st);
  const pressed = await page.evaluate(r => { const a = document.activeElement; return [a && a.dataset.rate === r && a.dataset.r, a && a.getAttribute('aria-pressed')]; }, R0);
  check(pressed[0] === 'partly' && pressed[1] === 'true', 'the pressed rating keeps the focus and reads aria-pressed true' + tag, pressed);
  await page.click(`${pane} [data-rate="${R0}"][data-r="knew"]`);
  st = await v2State(page);
  check(st.ev.length === 1 && st.ev[0].r === 'knew', 'a second rating of the same opening replaces the first (one rating, now Knew)' + tag, st.ev);
  await page.click(`${pane} [data-reveal="${R0}"]`);     // Hide again
  await page.click(`${pane} [data-reveal="${R0}"]`);     // Reveal: a new opening
  check(await page.$eval(`${pane} tr.dlt-recall[data-for="${R0}"] [data-ratenote]`, p => p.textContent) === 'Not counted until you choose one.', 'a new opening starts unrated' + tag);
  await page.click(`${pane} [data-rate="${R0}"][data-r="forgot"]`);
  await v2Reload(page);                                    // at once: the core writes on pagehide
  st = await v2State(page);
  check(Array.isArray(st.stored) && st.stored.length === 2 && st.stored.map(e => e.r).join() === 'knew,forgot' && st.stored.every(e => e.f === F0),
        'after a reload straight after the rating, the stored progress holds both ratings (Knew, then Forgot)' + tag, st.stored);
  check(!JSON.stringify(st.stored).includes('typed text') && !(await page.evaluate(() => JSON.stringify(localStorage).includes('typed text'))), 'what was typed is in no stored record' + tag);
  await v2Open(page, 'indication');
  const s1 = await statusOf(page, R0);
  check(new RegExp(`^Common indications: last rated Forgot on \\w{3} \\d{1,2}, \\d{4} \\(2 ratings\\) · bank questions: Not practised$`).test(s1 || ''),
        'after the reload the status line reads the stored ratings: last rated Forgot (2 ratings)' + tag, s1);

  // Not yet Knew: R1 rated Knew drops out; R0 (last Forgot) and unrated rows stay
  await page.click(`${pane} [data-reveal="${R1}"]`); await page.click(`${pane} [data-rate="${R1}"][data-r="knew"]`);
  const all = await page.$$eval(`${pane} tr[data-ref]`, t => t.length);
  await page.click(`${pane} [data-dl="notknew"]`);
  const refs = await page.$$eval(`${pane} tr[data-ref]`, t => t.map(x => x.dataset.ref));
  check(refs.length === all - 1 && !refs.includes(R1) && refs.includes(R0), `Not yet Knew hides the one row last rated Knew (${all} rows, then ${refs.length})` + tag, {all, n: refs.length});
  await page.click(`${pane} [data-dl="notknew"]`);
  await page.selectOption(`${pane} [data-dl="ask"]`, 'essential');
  check(/^Essential knowledge: not rated yet · bank question: Not practised$/.test(await statusOf(page, R1) || ''), 'each field is its own fact: R1\'s essential knowledge is not rated, with its own bank question' + tag, await statusOf(page, R1));

  // bank answers are read, never written, by the tab; a rating never changes them
  const before = await v2State(page);
  await page.evaluate(() => { record(byId('s1-1'), 'correct', 0, 1000); });
  await page.click(`#nav button[data-v="${V2_OPT.tab}"]`); await page.selectOption(`${pane} [data-dl="ask"]`, 'indication');
  let s2 = await statusOf(page, R0);
  check(/^Common indications: last rated Forgot on .+ \(2 ratings\) · bank questions: Remembered \(1 answer\)$/.test(s2 || ''), 'a right answer to one of the two mapped bank questions shows Remembered (1 answer); the ratings line is unchanged' + tag, s2);
  await page.selectOption(`${pane} [data-dl="ask"]`, 'essential');
  const s3 = await statusOf(page, R1);
  check(/^Essential knowledge: not rated yet · bank question: Not practised$/.test(s3 || ''), 'an answer to s1-1 leaves a fact only s1-2 tests Not practised: each fact reads only its own questions' + tag, s3);
  await page.selectOption(`${pane} [data-dl="ask"]`, 'indication');
  await page.evaluate(() => { record(byId('s1-2'), 'wrong', 1, 1000); });
  await page.click(`#nav button[data-v="${V2_OPT.tab}"]`); await page.selectOption(`${pane} [data-dl="ask"]`, 'indication');
  s2 = await statusOf(page, R0);
  check(/^Common indications: last rated Forgot on .+ \(2 ratings\) · bank questions: Forgot \(2 answers\)$/.test(s2 || ''), 'the last answer wrong: Forgot (2 answers), the two mapped questions read together; the ratings line is unchanged' + tag, s2);
  let after = await v2State(page);
  check(after.answers === before.answers + 2 && JSON.stringify(after.ev) === JSON.stringify(before.ev), 'two bank answers add two answers and no rating; the ratings are unchanged' + tag, {before: before.answers, after: after.answers});
  await page.click(`${pane} [data-reveal="${R0}"]`); await page.click(`${pane} [data-rate="${R0}"][data-r="partly"]`);
  after = await v2State(page);
  check(after.answers === before.answers + 2 && after.qn === before.qn + 2 && after.ev.length === before.ev.length + 1,
        'a rating adds one rating and no answer: each event is counted once, in its own part' + tag, {answers: after.answers, qn: after.qn, ev: after.ev.length});
  const wk = await page.evaluate(() => DB.answers.filter(a => !QUESTIONS.some(q => q.id === a.qid)).length);
  check(wk === 0, 'every answer in the progress is a bank question\'s (no Drug list item in DB.answers)' + tag, wk);

  // the per-tab record (#69) carries the part
  // the record is written with the core's save (150 ms timer): wait for it, up to 3 s
  await page.waitForFunction(n => { try { const r = JSON.parse(localStorage.getItem(myPendingKey()) || 'null'); return r && r.db && r.db.drugs && r.db.drugs.ev.length === n; } catch(e){ return false; } }, after.ev.length, {timeout: 3000}).catch(() => {});
  const pend = await page.evaluate(() => { try { const r = JSON.parse(localStorage.getItem(myPendingKey()) || 'null'); return r && r.db && r.db.drugs ? r.db.drugs.ev.length : null; } catch(e){ return 'err'; } });
  check(pend === after.ev.length, `this tab's own record (#69) holds DB.drugs with its ${after.ev.length} ratings` + tag, pend);

  // profiles: another profile has none of them; its own are kept apart
  const mine = after.ev;
  await page.evaluate(() => useProfile('dlo-other'));
  await page.waitForFunction(() => PROFILE === 'dlo-other', null, {timeout: 6000});
  st = await v2State(page);
  check(st.ev === null, 'another profile holds no ratings' + tag, st.ev);
  await v2Open(page, 'indication');
  check(/^Common indications: not rated yet/.test(await statusOf(page, R0) || ''), 'its status line: not rated yet' + tag);
  // the rows revealed stay revealed for the visit, as in v1, across a profile switch
  if(!(await page.$(`${pane} [data-rate="${R0}"]`))) await page.click(`${pane} [data-reveal="${R0}"]`);
  check(await page.$eval(`${pane} tr.dlt-recall[data-for="${R0}"] [data-ratenote]`, p => p.textContent) === 'Not counted until you choose one.', 'in the other profile the open row is unrated: a rating of the first profile is not carried over' + tag);
  await page.click(`${pane} [data-rate="${R0}"][data-r="knew"]`);
  await page.evaluate(n => useProfile(n), before.profile);
  await page.waitForFunction(n => PROFILE === n, before.profile, {timeout: 6000});
  await v2Reload(page);
  st = await v2State(page);
  check(JSON.stringify(st.ev) === JSON.stringify(mine), `after the switch back and a reload, the first profile holds its ${mine.length} ratings, unchanged` + tag, st.ev && st.ev.length);
  const other = await page.evaluate(() => { const d = JSON.parse(localStorage.getItem(NS + ':data:dlo-other') || 'null'); return d && d.drugs ? d.drugs.ev : null; });
  check(other && other.length === 1 && other[0].r === 'knew', 'the other profile\'s one rating is stored under it alone' + tag, other);

  // Export, Erase my history, Import back
  await page.evaluate(() => show('settings'));
  const [dl] = await Promise.all([page.waitForEvent('download'), page.click('#btnExport')]);
  const fileText = fs.readFileSync(await dl.path(), 'utf8'), exported = JSON.parse(fileText);
  check(exported.db && exported.db.drugs && JSON.stringify(exported.db.drugs.ev) === JSON.stringify(mine), `Export progress includes DB.drugs, its ${mine.length} ratings as stored` + tag);
  await page.click('#btnReset');
  await v2Reload(page);
  st = await v2State(page);
  check(st.ev === null && st.stored === null && st.answers === 0, 'Erase my history clears the ratings with the answers, also after a reload' + tag, st);
  const f = path.join(require('os').tmpdir(), `dlo-${process.pid}-${width}.json`);
  fs.writeFileSync(f, fileText);
  await page.evaluate(() => show('settings'));
  await page.setInputFiles('#fileIn', f);
  await page.waitForFunction(() => { const b = document.getElementById('importPlan'); return b && b.textContent.trim(); }, null, {timeout: 5000}).catch(() => {});
  if(await page.$('#importGo')){ await page.click('#importGo'); await page.waitForSelector('#importResult', {timeout: 5000}).catch(() => {}); }
  await v2Reload(page);
  st = await v2State(page);
  check(JSON.stringify(st.stored) === JSON.stringify(mine) && st.profile === before.profile, 'Import of that file into the erased profile puts the ratings back, also after a reload' + tag, {profile: st.profile, n: st.stored && st.stored.length});
  fs.rmSync(f, {force: true});
  check(!(await sideways(page)), 'no sideways scroll' + tag);
  check(!errors.length && !(await page.evaluate(() => window.__cerr)).length, 'no page or console error' + tag, errors.concat(await page.evaluate(() => window.__cerr)).slice(0, 3));
  await ctx.close();
}

/* "Kept on a later day" (DEENT drugfacts.js status(), for the ratings as the DEENT session gave
   it on 2026-11-09), with the core's dayKey: ratings planted on chosen days, read after a reload */
async function v2Days(browser, file){
  // in America/Chicago, so that the browser's day (dayKey) and the UTC day differ late in the evening
  const {ctx, page, errors} = await L.openPage(browser, file, {viewport: {width: 820, height: 900}, timezoneId: 'America/Chicago'}, consoleTrap);
  const ids = FIX.tables[0].rows.map(r => slugOf(r.generic));
  const day = (d, h, m) => [d, h, m || 0];      // made into a time in the page, in its time zone (November 2026)
  const cases = [
    // row 0's fact also has bank questions, whose part follows the ratings
    ['2:0', [['knew', day(2, 12)], ['knew', day(3, 12)]], /\(2 ratings; Kept on a later day\) · bank questions: /, 'Knew on 11/2, then Knew on 11/3: Kept on a later day'],
    ['2:1', [['knew', day(2, 9)], ['knew', day(2, 20)]], /on Nov 2, 2026 \(2 ratings\)$/, 'Knew twice on one day: Knew, not Kept (same-day repeats never count)'],
    ['2:2', [['knew', day(2, 12)], ['partly', day(3, 12)], ['knew', day(4, 12)]], /last rated Knew on Nov 4, 2026 \(3 ratings\)$/, 'Knew, Partly, Knew on three days: the Partly breaks the run, not Kept'],
    ['2:3', [['knew', day(2, 12)], ['knew', day(3, 12)], ['forgot', day(4, 12)]], /last rated Forgot on Nov 4, 2026 \(3 ratings\)$/, 'two Knew days, then Forgot: Forgot'],
    ['2:4', [['knew', day(2, 23, 30)], ['knew', day(3, 0, 30)]], /\(2 ratings; Kept on a later day\)$/, 'Knew at 23:30 and at 00:30 the next day: two calendar days (dayKey), Kept'],
    ['2:5', [['knew', day(3, 12)], ['knew', day(2, 12)]], /last rated Knew on Nov 3, 2026 \(2 ratings; Kept on a later day\)$/, 'ratings read in time order, whatever their order in the list'],
  ];
  await page.evaluate(([cs, ids]) => { const t = ([d, h, m]) => new Date(2026, 10, d, h, m).getTime();
    DB.drugs = {v: 1, ev: cs.flatMap(([ref, rs]) => rs.map(([r, at]) => ({f: ids[+ref.split(':')[1]] + ':indication', r, at: t(at)})))}; save(); }, [cases.map(c => c.slice(0, 2)), ids]);
  // bank answers on two days, read with the same day rule: Kept on a later day
  await page.evaluate(([da, db]) => { const t = ([d, h, m]) => new Date(2026, 10, d, h, m).getTime(), a = t(da), b = t(db), o = Date.now; try { Date.now = () => a; record(byId('s1-1'), 'correct', 0, 1000); Date.now = () => b; record(byId('s1-2'), 'correct', 0, 1000); } finally { Date.now = o; } save(); }, [day(2, 12), day(3, 12)]);
  await v2Reload(page);
  await v2Open(page, 'indication');
  for(const [ref, , re, what] of cases){
    const t = await statusOf(page, '0:' + ref.split(':')[1]);
    check(re.test(t || ''), 'v2 days: ' + what, t);
  }
  const b = await statusOf(page, '0:0');
  check(/· bank questions: Kept on a later day \(2 answers\)$/.test(b || ''), 'v2 days: bank answers right on 11/2 and 11/3: Kept on a later day (2 answers)', b);
  check(!errors.length, 'v2 days: no page error', errors.slice(0, 3));
  await ctx.close();
}

/* The note under the ratings says "Saved" only when the rating is stored (the review of #92, M1):
   the normal save, a write the browser refuses, a stale second tab without Web Locks. And the
   2,000-rating cap, by time, with its storage measured. */
const noteOf = (page, ref) => page.$eval(`${pane} tr.dlt-recall[data-for="${ref}"] [data-ratenote]`, p => [p.dataset.saved, p.textContent.replace(/\s+/g, ' ').trim()]).catch(() => [null, null]);
const storedEv = page => page.evaluate(() => { try { const d = JSON.parse(localStorage.getItem(NS + ':data:' + PROFILE) || 'null'); return d && d.drugs ? d.drugs.ev : null; } catch(e){ return 'unreadable'; } });
async function v2Saved(browser, file){
  const R0 = '0:0';
  // the normal path: the note is read at once after the click
  {
    const {ctx, page} = await L.openPage(browser, file, {viewport: {width: 820, height: 900}}, consoleTrap);
    await v2Open(page, 'indication');
    await page.click(`${pane} [data-reveal="${R0}"]`); await page.click(`${pane} [data-rate="${R0}"][data-r="knew"]`);
    const n = await noteOf(page, R0), st = await storedEv(page);
    check(n[0] === '1' && n[1] === 'Saved in this profile\'s progress: Knew.' && Array.isArray(st) && st.length === 1 && st[0].r === 'knew',
          'save: right after the click the note says Saved, and the stored progress holds the rating', {n, st});
    // where the core writes progText(DB) (a part kept outside localStorage, #81), the comparison uses it:
    // a stored text equal to progText(DB) and not to JSON.stringify(DB) is stored; without progText it is not
    const pt = await page.evaluate(() => { const k = keyFor(PROFILE), was = localStorage.getItem(k), api = FX.api('drug-list-tab');
      window.progText = db => 'progress-as-written:' + db.answers.length;
      localStorage.setItem(k, progText(DB)); const withPt = api.stored();
      delete window.progText; const withoutPt = api.stored(); localStorage.setItem(k, was); return {withPt, withoutPt, back: api.stored()}; });
    check(pt.withPt === true && pt.withoutPt === false && pt.back === true, 'save: the stored text is compared with progText(DB) when the core has it, else with JSON.stringify(DB)', pt);
    await ctx.close();
  }
  // the browser refuses the write of the progress
  {
    const refuse = () => { const o = Storage.prototype.setItem; Storage.prototype.setItem = function(k, v){ if(window.__refuse && String(k).includes(':data:')) throw new DOMException('quota', 'QuotaExceededError'); return o.apply(this, arguments); }; };
    const {ctx, page} = await L.openPage(browser, file, {viewport: {width: 820, height: 900}}, refuse);
    await v2Open(page, 'indication');
    await page.evaluate(() => { window.__refuse = true; });
    await page.click(`${pane} [data-reveal="${R0}"]`); await page.click(`${pane} [data-rate="${R0}"][data-r="knew"]`);
    const n = await noteOf(page, R0), st = await storedEv(page), failed = await page.evaluate(() => FAILED.has(keyFor(PROFILE)));
    check(failed && st === null && n[0] === '0' && /^Not saved: Knew is on this page only\./.test(n[1] || ''),
          'save: with the write refused (FAILED), the note says Not saved, and nothing is stored', {failed, st, n});
    await ctx.close();
  }
  // a stale second tab, without Web Locks: the other tab saved since this one loaded
  {
    const noLocks = () => { try { Object.defineProperty(Navigator.prototype, 'locks', {get(){ return undefined; }, configurable: true}); } catch(e){} };
    const {ctx, page: a} = await L.openPage(browser, file, {viewport: {width: 820, height: 900}}, noLocks);
    const b = await ctx.newPage(); await b.goto(a.url()); await b.waitForFunction(() => document.querySelectorAll('#nav button').length > 3, null, {timeout: 15000});
    const locks = await a.evaluate(() => HAS_LOCKS);
    await v2Open(a, 'indication'); await v2Open(b, 'indication');
    await a.click(`${pane} [data-reveal="${R0}"]`); await a.click(`${pane} [data-rate="${R0}"][data-r="knew"]`);
    await b.waitForFunction(() => { try { const d = JSON.parse(localStorage.getItem(NS + ':data:' + PROFILE) || 'null'); return d && d.drugs; } catch(e){ return false; } }, null, {timeout: 5000}).catch(() => {});
    await b.click(`${pane} [data-reveal="${R0}"]`); await b.click(`${pane} [data-rate="${R0}"][data-r="forgot"]`);
    const na = await noteOf(a, R0), nb = await noteOf(b, R0), st = await storedEv(b);
    check(locks === false && na[0] === '1' && nb[0] === '0' && /^Not saved: Forgot is on this page only\./.test(nb[1] || '') && Array.isArray(st) && st.length === 1 && st[0].r === 'knew',
          'save: in a stale second tab without Web Locks, the note says Not saved; the store holds only the other tab\'s rating', {locks, na, nb, st});
    await ctx.close();
  }
}
async function v2Cap(browser, file){
  const {ctx, page} = await L.openPage(browser, file, {viewport: {width: 820, height: 900}}, consoleTrap);
  const ids = FIX.tables.flatMap(t => t.rows.map(r => slugOf(r.generic)));
  const base = Date.UTC(2026, 9, 1);
  // 2,000 ratings, one minute apart, stored newest first (as an Import or a replaced rating can leave them)
  const plan = Array.from({length: 2000}, (_, k) => ({f: ids[k % ids.length] + ':indication', r: ['forgot', 'partly', 'knew'][k % 3], at: base + k * 60000})).reverse();
  const empty = await page.evaluate(() => (localStorage.getItem(NS + ':data:' + PROFILE) || JSON.stringify(DB)).length);
  await page.evaluate(ev => { DB.drugs = {v: 1, ev}; save(); saveNow(); }, plan);
  await v2Reload(page);
  const full = await page.evaluate(() => ({data: (localStorage.getItem(NS + ':data:' + PROFILE) || '').length, part: JSON.stringify(DB.drugs).length,
    rec: (() => { try { const r = JSON.parse(localStorage.getItem(myPendingKey()) || 'null'); return r && r.db && r.db.drugs ? JSON.stringify(r.db.drugs).length : null; } catch(e){ return null; } })()}));
  await v2Open(page, 'indication');
  await page.click(`${pane} [data-reveal="0:0"]`); await page.click(`${pane} [data-rate="0:0"][data-r="partly"]`);
  // this tab's own record (#69) is written with its next save: it holds the part again
  await page.waitForFunction(() => { try { const r = JSON.parse(localStorage.getItem(myPendingKey()) || 'null'); return r && r.db && r.db.drugs && r.db.drugs.ev.length === 2000; } catch(e){ return false; } }, null, {timeout: 3000}).catch(() => {});
  full.rec = await page.evaluate(() => { try { const r = JSON.parse(localStorage.getItem(myPendingKey()) || 'null'); return r && r.db && r.db.drugs ? JSON.stringify(r.db.drugs).length : null; } catch(e){ return null; } });
  await v2Reload(page);
  const ev = await storedEv(page), ats = Array.isArray(ev) ? ev.map(e => e.at) : [];
  const oldest = base, newestPlanted = base + 1999 * 60000;
  check(Array.isArray(ev) && ev.length === 2000 && !ats.includes(oldest) && ats.includes(newestPlanted) && ats.includes(base + 60000) && ev.some(e => e.r === 'partly' && e.at > newestPlanted),
        'cap: 2,000 ratings stored newest first, one more rating, a reload: 2,000 kept, the oldest by time gone, the newest planted and the new one kept', {n: ev && ev.length, oldestKept: ats.includes(oldest), newestKept: ats.includes(newestPlanted)});
  console.log(`  report  cap: the progress text is ${empty} characters with no ratings and ${full.data} with 2,000 (the DB.drugs part: ${full.part}); this tab's own record holds the part again: ${full.rec}`);
  check(full.part > 0 && full.data - empty >= full.part && full.rec > 0, `cap: the ratings part at 2,000 ratings measured (${full.part} characters), in the progress and again in this tab's own record (${full.rec})`, full);
  await ctx.close();
}

/* What Import does with a file when only the ratings differ (core/README.md 805-816): measured,
   reported, and checked against the rule as the README states it. */
async function v2ImportMeasure(browser, file){
  const {ctx, page} = await L.openPage(browser, file, {viewport: {width: 820, height: 900}}, consoleTrap);
  page.on('dialog', d => d.accept().catch(() => {}));
  const exportNow = async () => { await page.evaluate(() => show('settings'));
    const [dl] = await Promise.all([page.waitForEvent('download'), page.click('#btnExport')]); return fs.readFileSync(await dl.path(), 'utf8'); };
  const planOf = async text => { const f = path.join(require('os').tmpdir(), `dlo-m-${process.pid}-${Math.random().toString(36).slice(2)}.json`); fs.writeFileSync(f, text);
    await page.evaluate(() => { if(!window.__planWrapped){ const o = showImportPlan; showImportPlan = p => { window.__plan = p; return o(p); }; window.__planWrapped = 1; } window.__plan = null; show('settings'); });
    await page.setInputFiles('#fileIn', f);
    await page.waitForFunction(() => { const b = document.getElementById('importPlan'); return b && b.textContent.trim(); }, null, {timeout: 5000}).catch(() => {});
    const plan = await page.evaluate(() => (document.getElementById('importPlan') || {}).textContent || ''); fs.rmSync(f, {force: true});
    const action = await page.evaluate(() => window.__plan ? window.__plan.action : null);
    return {action, text: plan.replace(/\s+/g, ' ').trim()}; };
  const texts = [];
  const kind = p => { texts.push(p.text); return p.action || 'no plan: ' + p.text.slice(0, 80); };
  const rate = async (ref, r) => { await v2Open(page, 'indication'); if(!(await page.$(`${pane} [data-rate="${ref}"]`))) await page.click(`${pane} [data-reveal="${ref}"]`);
    await page.click(`${pane} [data-rate="${ref}"][data-r="${r}"]`); };
  await page.evaluate(() => { record(byId('s1-1'), 'correct', 0, 1000); record(byId('s1-2'), 'correct', 0, 1000); });
  await rate('0:0', 'partly');
  const A = await exportNow();
  const res = [];
  res.push(['M1 the same file again (answers and ratings as here)', kind(await planOf(A)), 'nothing']);
  await rate('0:1', 'knew');          // a rating here, no answer: this profile is ahead of the file by one rating
  res.push(['M2 an older file of this profile, behind it by one rating and no answer', kind(await planOf(A)), 'separate']);
  const B = JSON.parse(await exportNow());
  const C = JSON.parse(JSON.stringify(B)); C.db.drugs.ev.push({f: ID1 + ':essential', r: 'forgot', at: Date.now()});
  res.push(['M3 a file with the same answers and one more rating (rated on another device)', kind(await planOf(JSON.stringify(C))), 'separate']);
  const D = JSON.parse(JSON.stringify(B)); delete D.db.drugs;
  // the file adds nothing this profile lacks (Import compares every part of the file with this profile's, addsTo,
  // core/README.md 792-800), so nothing changes and nothing is lost
  res.push(['M4 a file with the same answers and no ratings', kind(await planOf(JSON.stringify(D))), 'nothing']);
  console.log('\n  Import with ratings only differing (REPORT, core/README.md 805-816):');
  res.forEach(([what, got, rule], k) => console.log(`  report  ${what}: ${got} (the README's rule: ${rule}); the plan: "${texts[k]}"`));
  for(const [what, got, rule] of res){
    check(got === rule, `Import measure, ${what}: ${got}, as the README's rule says`, got); }
  await ctx.close();
  return res;
}

(async () => {
  console.log('\n=== the course\'s own drug tables ===');
  L.PAGE.need(NAME);
  const X = L.engine('({T: typeof DRUG_TABLES === "undefined" ? null : DRUG_TABLES, FX})');
  hasOwn = !!X.T;
  const feat = (X.FX.modules().find(m => m.name === 'drug-list-tab') || {});
  if(!X.T) L.skip('the course\'s own drug tables', 'course.js lists no data file that declares DRUG_TABLES');
  else {
    const o = feat.options || {};
    check(X.FX.tabs().includes(o.tab || DEFAULTS.tab), `the course's ${X.T.length} tables have the tab (#v-${o.tab || DEFAULTS.tab})`, X.FX.tabs());
    const {browser} = await L.launch(NAME);
    try {
      const {ctx, page, errors} = await L.openFile(browser);
      await page.click(`#nav button[data-v="${o.tab || DEFAULTS.tab}"]`);
      if(o.groups && o.groups.length) await page.click(`#v-${o.tab || DEFAULTS.tab} [data-listgroup="-1"]`);
      const got = await page.$$eval(`#v-${o.tab || DEFAULTS.tab} [data-body] section[data-table]`, s => s.map(e => [e.dataset.table, e.querySelectorAll('tbody tr[data-ref]').length]));
      check(JSON.stringify(got) === JSON.stringify(X.T.map(t => [String(t.id), t.rows.length])), `the tab draws every one of the course's tables with every row (${got.length})`, got.slice(0, 3));
      check(!errors.length, 'no page error on the course\'s own page', errors.slice(0, 3));
      await ctx.close();
    } finally { await browser.close(); }
  }

  console.log('\n=== the build step refuses bad data ===');
  const T = FIX.tables;
  const refuse = [
    ['a table with no id', 'noid', (() => { const t = clone(T); delete t[0].id; return t; })(), BDK_OPT, /table 1 has no id/],
    ['a table with no rows', 'norows', (() => { const t = clone(T); t[1].rows = []; return t; })(), BDK_OPT, /table "3" has no rows/],
    ['a group naming a table that does not exist', 'nogroup', T, opts(Object.assign({}, BDK_OPT, {groups: FIX.groups.concat([{label: 'Week 99', tables: [99]}])})), /group "Week 99" names the table "99", which DRUG_TABLES does not have/],
    ['a column naming a field no row has', 'nocol', T, opts(Object.assign({}, BDK_OPT, {columns: BDK_OPT.columns.concat([['schedule', 'Schedule']])})), /option columns names the field "schedule", which no row has/],
    ['images for some tables but not all', 'someimg', (() => { const t = clone(T); t[0].image = 'pages/p2.webp'; return t; })(), BDK_OPT, /1 of 26 tables give an image: give every table an image, or none/],
    ['a recallShow field no row has', 'norecallshow', T, opts(Object.assign({}, BDK_OPT, {recallShow: ['generic', 'schedule']})), /option recallShow names the field "schedule", which no row has/],
    ['a recallClassField no row has', 'norecallcls', T, opts(Object.assign({}, BDK_OPT, {recallClassField: 'schedule'})), /option recallClassField names the field "schedule", which no row has/],
    ['a default group that is not a group', 'nodefault', T, opts(Object.assign({}, BDK_OPT, {defaultGroup: 'Week 15'})), /option defaultGroup is "Week 15", which is not the label of a group/],
  ];
  for(const [what, label, tables, o, re] of refuse){
    const b = build('dlt-' + label, tables, o);
    check(b.code !== 0 && re.test(b.out) && !fs.existsSync(b.page), `${what}: the build stops with "${re.source.replace(/\\/g, '')}"`, b.out.split('\n').pop());
    b.rm();
  }
  for(const [what, label, tables, o, facts, re] of v2Refuse()){
    const b = buildV2('dlt-' + label, tables, o, facts);
    check(b.code !== 0 && re.test(b.out) && !fs.existsSync(b.page), `v2, ${what}: the build stops with "${re.source.replace(/\\/g, '')}"`, b.out.split('\n').pop());
    b.rm();
  }

  console.log('\n=== BDK\'s list in the browser (scratch copy) ===');
  const s = build('dlt-bdk', T, BDK_OPT);
  if(s.code !== 0) L.notRun(NAME, 'the scratch copy with BDK\'s tables does not build: ' + s.out.split('\n').pop());
  const o2 = opts({tab: 'druglist', label: 'Drugs', columns: [['generic', 'Generic'], ['label', 'Listed as', 'activity', 'Activity against: ']], searchFields: ['generic'], groups: [], defaultGroup: '',
    recallDefault: true, recallShow: ['label'], recallClassField: ''});
  const s2 = build('dlt-opts', T.map(t => Object.assign({}, t, {image: `pages/p${t.id}.webp`, imageSize: BDK_PAGE_IMG[t.id]})), o2);
  // a sub-field named in recallShow shows before Reveal: one column, BDK's activity as its sub-field, the BDK tables
  // that have activity text (whole, as they are)
  const actTables = T.filter(t => t.rows.some(r => r.activity));
  const o3 = opts({columns: [['generic', 'Generic', 'activity', 'Activity against: ']], searchFields: ['generic'], groups: [], defaultGroup: '',
    recallDefault: true, recallShow: ['generic', 'activity'], recallClassField: ''});
  const s3 = build('dlt-subshow', actTables, o3);
  const s4 = buildV2('dlt-v2', T, V2_OPT, V2_FACTS);
  const {browser} = await L.launch(NAME);
  try {
    for(const w of [390, 820]){ console.log(`\n--- ${w} px ---`); await bdkView(browser, s.page, w); }
    for(const w of [390, 820]){ console.log(`\n--- recall mode, ${w} px ---`); await recallView(browser, s.page, w); }
    console.log('\n=== other options (scratch copy: tab, label, columns, searched fields, no groups, an image per table) ===');
    if(s2.code !== 0) check(false, 'the scratch copy with other options builds', s2.out.split('\n').pop());
    else await optionView(browser, s2.page, o2);
    console.log('\n=== a sub-field named in recallShow (scratch copy: one column, the tables with activity text) ===');
    if(s3.code !== 0) check(false, 'the scratch copy with a shown sub-field builds', s3.out.split('\n').pop());
    else {
      const {ctx, page} = await L.openPage(browser, s3.page, {viewport: {width: 820, height: 900}}, consoleTrap);
      await page.click(`#nav button[data-v="${BDK_OPT.tab}"]`);
      const want = actTables.flatMap((t, ti) => t.rows.map((r, i) => [`${ti}:${i}`, r.activity]).filter(x => x[1]));
      const got = await page.evaluate(([tab, want]) => want.map(([ref, a]) => { const tr = document.querySelector(`#v-${tab} tr[data-ref="${ref}"]`);
        return !!tr && tr.textContent.includes(a); }), [BDK_OPT.tab, want]);
      const on = await page.$eval(`#v-${BDK_OPT.tab} [data-dl="recall"]`, b => b.getAttribute('aria-pressed'));
      check(on === 'true' && want.length > 0 && got.every(Boolean), `with recall on, a sub-field named in recallShow is shown before Reveal (activity on ${want.length} rows)`, {on, n: want.length, missing: got.filter(x => !x).length});
      await ctx.close();
    }
    console.log('\n=== v2: ratings kept in the progress (scratch copy: recallFields and DRUG_FACTS) ===');
    if(s4.code !== 0) check(false, 'the scratch copy with recallFields and DRUG_FACTS builds', s4.out.split('\n').pop());
    else {
      check(/build step done/.test(s4.out), 'the v2 copy builds');
      for(const w of [390, 820]){ console.log(`\n--- v2, ${w} px ---`); await v2View(browser, s4.page, w); }
      console.log('\n--- v2, Kept on a later day ---');
      await v2Days(browser, s4.page);
      console.log('\n--- v2, the note says Saved only when stored ---');
      await v2Saved(browser, s4.page);
      console.log('\n--- v2, the 2,000-rating cap ---');
      await v2Cap(browser, s4.page);
      console.log('\n--- v2, Import measured ---');
      await v2ImportMeasure(browser, s4.page);
    }
    {
      const {ctx, page} = await L.openPage(browser, s.page, {viewport: {width: 820, height: 900}});
      await page.click(`#nav button[data-v="${BDK_OPT.tab}"]`); await page.click(`${pane} [data-dl="recall"]`);
      check(!(await page.$(`${pane} [data-dl="ask"]`)), 'with recallFields empty (the default) recall mode has no Ask for and rates nothing (v1)');
      await ctx.close();
    }
  } finally {
    await browser.close();
    s.rm(); s2.rm(); s3.rm(); s4.rm();
  }
  L.finish(NAME);
})().catch(e => { console.log('FAIL: ' + NAME + ': crashed: ' + (e && e.stack || e)); process.exit(1); });
